INSERT INTO `tb_latest_updates` (`id`, `title`, `type_id`, `home_view_status`, `hyperlink`, `description`, `short_description`, `file_upload`, `guru_id`, `programme_id`, `pgm_type`, `share_image`, `cover_image`, `image_caption`, `alt_value`, `media_date`, `newspaper`, `media_file`, `website_url`, `target_type`, `status`, `added_on`, `added_by`, `added_ip`, `last_updated_on`, `last_updated_by`, `last_updated_by_ip`, `deleted_on`, `deleted_by`, `deleted_by_ip`, `filename`, `meta_title`, `meta_keywords`, `meta_description`) VALUES
(1, 'Intermediate Lessons', 1, 'n', NULL, '<p>NatyaSutraOnline is happy to announce that intermediate classes shall be released soon on all our platforms. Personally crafted by Guru Pali Chandra, this series aims at helping students who have either finished the beginners&#39; program or for those with a pre-existing background in Kathak. It is the perfect transition towards further enriching your journey in the path of Kathak.</p>', '', NULL, 0, 3, 'd', '', 'kathak-intermediate-classes-to-be-released-soon.jpg', '', 'Intermediate Lessons', '1970-01-01', '', '', '', 0, 0, '2019-10-01 17:07:27', 1, '59.95.75.188', '2026-06-29 04:18:58', 19, '223.181.12.45', NULL, NULL, NULL, 'intermediate-lessons', 'Intermediate Lessons', 'Intermediate Lessons', 'Intermediate Lessons'),
(2, 'Mohiniyattam by Smitha Rajan', 1, 'n', NULL, '<p xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\">Smitha Rajan is a third-generation exponent of Mohiniyattam, a key figure in the drive to revitalize classical Indian dance globally. The granddaughter of legendary artist Kalamandalam Kalyanikutty Amma, she has played a crucial role in reintroducing the general public to the core tenets of her art form. A traditionalist by all accounts, we are proud to announce her new series on Mohiniyattam compositions. </span></span></span></span></span></p>\r\n\r\n<p xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\">The padam titled, &#39;Padam Kanden Shyamala,&#39; is now exclusively available on NatyaSutraOnline.com. This series chronicles the mesmerizing bliss a mortal must endure in the presence of Lord Krishna. </span></span></span></span></span><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\"><span xss=\"removed\">The entire program is divided into sections with detailed explanations, demonstrations, and a live performance. </span></span></span></span></span></p>', '', NULL, 0, 15, 'd', '', 'mohiniyattam-by-smitha-rajan.jpg', '', 'Mohiniyattam by Smitha Rajan', '1970-01-01', '', '', '', 0, 0, '2019-12-19 17:07:30', 1, '61.2.215.220', '2026-06-29 04:18:44', 19, '223.181.12.45', NULL, NULL, NULL, 'mohiniyattam-by-smitha-rajan', 'Mohiniyattam by Smitha Rajan', 'Mohiniyattam by Smitha Rajan', 'Mohiniyattam by Smitha Rajan'),
(3, 'Panchakarma, Ayurveda\'s Premier Healthcare Regimen', 1, 'n', NULL, '<p xss=\"removed\">We are excited to present a special video presentation containing essential Panchakarma treatment methods. Ayurveda has played an integral role in Indian households for centuries, and Panchakarma represents the epitome of its healing prowess. Panchakarma is essentially a 5-step approach to holistic well-being, with an organic outlook towards a healthy lifestyle. This presentation has been carefully subdivided into 36 individual parts, each chronicling the benefits and nuances of the treatment. The lessons within will surely improve the physical, mental, and spiritual state of the individual. </p>', '', NULL, 0, 17, 'd', NULL, 'panchakarma-ayurvedas-premier-healthcare-regimen.jpg', NULL, 'Panchakarma, Ayurveda\'s Premier Healthcare Regimen', '1970-01-01', '', '', '', 0, 1, '2020-02-05 14:39:30', 1, '61.2.215.220', '2020-05-17 18:27:42', 1, '202.88.244.195', NULL, NULL, NULL, 'panchakarma-ayurvedas-premier-healthcare-regimen', 'Panchakarma, Ayurveda\'s Premier Healthcare Regimen', 'Panchakarma, Ayurveda\'s Premier Healthcare Regimen', 'Panchakarma, Ayurveda\'s Premier Healthcare Regimen'),
(4, 'Intermediate Lessons to be launched on International Women\'s Day!', 1, 'n', NULL, '<p xss=\"removed\"> </p>\r\n\r\n<p xss=\"removed\">NatyaSutraOnline, along with Guru Pali Chandra, salutes the brave individuals whose sacrifices have set the stage for a truly gender-equal world.</p>\r\n\r\n<p xss=\"removed\"><br>\r\nMarch 8th is universally celebrated as International Women’s Day, and to commemorate this special occasion, we are proud to announce the release of Guru Pali Chandra’s Intermediate Online Classes for Kathak.</p>\r\n\r\n<p xss=\"removed\">Our Indian classical dance forms represent the truest form of equality, where skill and perseverance are the only tools necessary to establish yourself.<br>\r\nThey filter against any form of discrimination and have encouraged all dancers to find their own equal footing in society for centuries.</p>\r\n\r\n<p xss=\"removed\"><br>\r\nThis International Women’s Day, NatyaSutraOnline joins hands with the #GenerationEquality proclamation of the UN.</p>\r\n\r\n<p xss=\"removed\">Guru Pali Chandra’s Intermediate  Kathak classes shall now be accessible for students across the globe.</p>', '', NULL, 0, 3, 'd', NULL, 'intermediate-lessons-to-be-launched-on-international-womens-day1.jpg', NULL, 'Intermediate Lessons to be launched on International Women\'s Day!', '1970-01-01', '', '', '', 0, 1, '2020-02-24 17:32:55', 1, '202.88.244.195', '2020-05-17 18:27:06', 1, '202.88.244.195', NULL, NULL, NULL, 'intermediate-essons-international-womens-day', 'Intermediate Lessons to be launched on International Women\'s Day!', 'Intermediate Lessons to be launched on International Women\'s Day!', 'Intermediate Lessons to be launched on International Women\'s Day!'),
(5, 'Sri Chakra Raja... Mohiniyattam composition live now!', 1, 'n', NULL, '<p>The Goddess within each woman is explored to the fullest in &#39;Sri Chakra Raja...&#39; the newest Mohiniyattam composition by Guru Smitha Rajan. </p>\r\n\r\n<p>Our homes are the fulcrum around which our Universe functions. Age is no barrier while experiencing the true power of the female mystique. </p>\r\n\r\n<p>With in-depth explanations and demonstrations, classical dance aficionados across the spectrum can explore the wonders of this mystical force. <br>\r\nA new realm in Indian nritya is about to rear its head, as we usher in the era of the Sacred Female.</p>', '', NULL, 0, 18, 'd', NULL, 'sri-chakra-rajarajeshwari-composition-to-be-launched-on-april-14th.jpg', NULL, 'Sri Chakra Raja... Mohiniyattam composition live now!', '1970-01-01', '', '', '', 0, 1, '2020-03-18 17:27:34', 1, '202.88.244.195', '2020-05-17 18:26:00', 1, '202.88.244.195', NULL, NULL, NULL, 'sri-chakra-raja-mohiniyattam-composition', 'Sri Chakra Raja... Mohiniyattam composition live now!', 'Sri Chakra Raja... Mohiniyattam composition live now!', 'Sri Chakra Raja... Mohiniyattam composition live now!'),
(6, 'Panchakarma', 1, 'n', NULL, '', '', NULL, 0, 17, 'd', NULL, 'panchakarma.jpg', NULL, 'Panchakarma', '1970-01-01', '', '', '', 0, 0, '2020-03-26 20:58:48', 1, '223.228.135.87', '2020-05-17 18:24:50', 1, '202.88.244.195', NULL, NULL, NULL, 'panchakarma', 'Panchakarma', 'Panchakarma', 'Panchakarma'),
(7, 'Let us lock in dance', 1, 'n', NULL, '<p>Feel the panic mount?</p>\r\n\r\n<p>Let the nritya of our ancestors relax your senses. As the world combats COVID-19 and India enters an unprecedented 21-day lockdown, let&#39;s quarantine and jam to the compositions our forefathers preserved for us.</p>\r\n\r\n<p>These Indian classical dance videos have been handpicked by the NatyaSutraOnline team to redirect your mind in these trying times. They represent anthems, hymns, and personal productions that have a profound life lesson for all our viewers. So let&#39;s stay indoors and get our nritya on!</p>\r\n\r\n<p><a href=\"https://www.natyasutraonline.com/freeclass/let-us-lock-in-dance\">Click here to check out our free classes. </a></p>', '', NULL, 0, NULL, '', NULL, 'panchakarma1.jpg', '', 'Let us lock in dance', '1970-01-01', '', '', '', 0, 1, '2020-03-26 20:58:51', 1, '223.228.135.87', '2023-06-13 05:25:49', 10, '49.37.235.73', NULL, NULL, NULL, 'let-us-lock-in-dance', 'Let us lock in dance', 'Let us lock in dance', 'Let us lock in dance'),
(8, 'Payaliya Tharana available now!', 1, 'n', NULL, '<p>The Anklet’s Whisper is finally here!  </p>\r\n\r\n<p>The Payalia Tarana is a mesmerizing new Kathak composition by Guru Pali Chandra, now streaming exclusively on NatyaSutraOnline.</p>\r\n\r\n<p>Drawing from Persian and Hindu roots, this union of cultures is a subtle take on love, yearning and overcoming obstacles in tough times.</p>\r\n\r\n<p>The Guru has devised a thorough regimen that contains solo and group demonstrations alongside detailed explanations regarding the overarching goals of the program.</p>', '', NULL, 0, 21, 'd', NULL, '', NULL, 'Payaliya Tharana available now!', '1970-01-01', '', '', '', 0, 0, '2020-03-27 14:25:39', 1, '117.199.0.224', '2023-02-24 07:24:40', 1, '61.2.215.254', NULL, NULL, NULL, 'payaliya-tharana-available-now', 'Payaliya Tharana available now!', 'Payaliya Tharana available now!', 'Payaliya Tharana available now!'),
(9, 'A tribute to legendary artist Dr. Maya Rao', 1, 'n', NULL, '<p>Remembering Dr. Maya Rao, the renowned dancer who amplified Kathak’s popularity in South India.<br>\r\nShe was awarded the Sangeet Natak Akademi Award in 1989.<br>\r\nShe received the first scholarship instituted by Government of India to learn Kathak under the guidance of Guru Shambu Maharaj of the Lucknow Gharana.</p>\r\n\r\n<p>On this International Dance Day, we pay our tribute to this legendary artist, without whom Kathak wouldn&#39;t have been in its present day glory in South India.</p>', '', NULL, 0, NULL, '', NULL, 'a-tribute-to-legendary-artist-dr-maya-rao.jpg', '', 'A tribute to legendary artist Dr. Maya Rao', '1970-01-01', '', '', '', 0, 1, '2020-04-24 15:27:04', 1, '137.97.124.181', '2023-06-13 05:25:33', 10, '49.37.235.73', NULL, NULL, NULL, 'tribute-legendary-artist-maya-rao', 'A tribute to legendary artist Dr. Maya Rao', 'A tribute to legendary artist Dr. Maya Rao', 'A tribute to legendary artist Dr. Maya Rao'),
(10, 'A tribute to exponent Rukmini Devi Arundale', 1, 'n', NULL, '<p>On this International Dance Day, let’s pay homage to Rukmini Devi Arundale, an admirable Bharatanatyam exponent who glorified classical dance in India.</p>\r\n\r\n<p>Rukmini Devi Arundale is the founder of Kalakshetra, a one-of-a-kind training institution for classical arts. <br>\r\nShe was an Indian theosophist, choreographer and an activist for animal rights & welfare. <br>\r\nShe was awarded the Padma Bhushan in 1956, and the Sangeet Natak Akademi Fellowship in 1967.</p>', '', NULL, 0, NULL, '', NULL, 'a-tribute-to-exponent-rukmini-devi-arundale.jpg', '', 'A tribute to exponent Rukmini Devi Arundale', '1970-01-01', '', '', '', 0, 1, '2020-04-25 10:50:24', 1, '137.97.124.181', '2023-06-13 05:24:30', 10, '49.37.235.73', NULL, NULL, NULL, 'tribute-exponent-rukmini-devi-arundale', 'A tribute to exponent Rukmini Devi Arundale', 'A tribute to exponent Rukmini Devi Arundale', 'A tribute to exponent Rukmini Devi Arundale'),
(11, 'Remembering Classical Theater Maestro', 1, 'n', NULL, '<p>A devoted artist who redefined Kerala&#39;s very own classical drama Kathakali.</p>\r\n\r\n<p>It is said that the modern history of Kathakali begins where the life history of Pattikkamthodi ends. <br>\r\nHe is renowned for reviving Kalluvazhi tradition of this art giving new grammar and steps.<br>\r\nThis International Dance Day, let&#39;s remember this distinguished artist who gave a new life and face to Kerala&#39;s classical tradition.</p>', '', NULL, 0, NULL, '', NULL, 'remembering-classical-theater-maestro.jpg', '', 'Remembering Classical Theater Maestro', '1970-01-01', '', '', '', 0, 1, '2020-04-26 12:56:39', 1, '137.97.169.6', '2023-06-13 05:25:14', 10, '49.37.235.73', NULL, NULL, NULL, 'remembering-classical-theater-maestro', 'Remembering Classical Theater Maestro', 'Remembering Classical Theater Maestro', 'Remembering Classical Theater Maestro'),
(12, 'Tribute to the Mother of Mohiniyattam', 1, 'n', NULL, '<p>A great artist who brought Kerala&#39;s very own classical Dance form Mohiniyattam into the mainstream of Indian classical dance giving it a formal structure and style. </p>\r\n\r\n<p>Revered as the Mother of Mohiniyattam, Kalyanikutty Amma received both the Kerala Sangeetha Nataka Academy and Kendra Sangeet Natak Akademi awards.<br>\r\nRemembering this legendary danseuse who offered her life to the art of dance, on this International Dance Day.</p>', '', NULL, 0, 18, 'd', NULL, 'tribute-to-the-mother-of-mohiniyattam.jpg', NULL, 'Tribute to the Mother of Mohiniyattam', '1970-01-01', '', '', '', 0, 0, '2020-04-27 13:45:08', 1, '59.98.97.36', '2020-05-17 18:20:14', 1, '202.88.244.195', '2020-04-28 13:20:38', 1, '202.88.244.195', 'tribute-to-the-mother-of-mohiniyattam', 'Tribute to the Mother of Mohiniyattam', 'Tribute to the Mother of Mohiniyattam', 'Tribute to the Mother of Mohiniyattam'),
(13, 'Pioneer of Odissi Dance', 1, 'n', NULL, '<p>A phenomenon, one of India’s most prominent dance legends, Guru Kelucharan Mohapatra introduced new techniques and styles into the classical art form Odissi.</p>\r\n\r\n<p>He is credited for the revival of the Odissi dance in the 20th century. Guru Kelucharan is the first person to get Padma Vibhushan from Odisha. <br>\r\nHe also received Padma Shri and Sangeet Natak Aademi award.</p>\r\n\r\n<p>Remembering this pioneer with whose effort Odissi came to be known worldwide and has a global presence.</p>', '', NULL, 0, NULL, '', NULL, 'pioneer-of-odissi-dance.jpg', '', 'Pioneer of Odissi Dance', '1970-01-01', '', '', '', 0, 1, '2020-04-28 14:52:35', 1, '202.88.244.195', '2023-06-13 05:24:07', 10, '49.37.235.73', NULL, NULL, NULL, 'pioneer-of-odissi-dance', 'Pioneer of Odissi Dance', 'Pioneer of Odissi Dance', 'Pioneer of Odissi Dance'),
(14, 'Bharatanatyam Compositions by Rajashree Warrier', 1, 'n', NULL, '<p>Much awaited Bharatanatyam sessions by the talented dancer Guru Rajashree Warrier will soon be available here! </p>\r\n\r\n<p>These compositions will be packed by detailed explanations and demonstrations for self learning purposes. </p>', '', NULL, 0, 29, 'd', NULL, 'bharatanatyam-compositions-by-rajashree-warrier.jpg', NULL, 'Bharatanatyam Compositions by Rajashree Warrier', '1970-01-01', '', '', '', 0, 0, '2020-05-06 14:16:40', 1, '137.97.103.90', '2023-02-24 07:24:05', 1, '61.2.215.254', NULL, NULL, NULL, 'coming-soon', 'Bharatanatyam Compositions by Rajashree Warrier', 'Bharatanatyam Compositions by Rajashree Warrier', 'Bharatanatyam Compositions by Rajashree Warrier'),
(15, 'World Dance Day 2020', 1, 'n', NULL, '<p>\"Art is something that makes you breathe with a different kind of happiness\"<br>\r\nAmidst this time of misery, we wish this International Dance Day brings home a glimpse of hope, happiness and positivity through art.</p>', '', NULL, 0, 0, 'd', NULL, '', NULL, 'World Dance Day 2020', '1970-01-01', '', '', '', 0, 0, '2020-05-09 09:04:07', 1, '223.228.190.79', '2020-06-08 12:58:04', 1, '202.88.244.195', NULL, NULL, NULL, 'dance-day', 'Dance Day', 'Dance Day', 'Dance Day'),
(16, 'Poothanamoksham Live Now!', 1, 'n', NULL, '<p>The Liberation of a Demoness is upon us!</p>\r\n\r\n<p>The Poothana Moksham or Deliverance of Poothana is now streaming exclusively on NatyaSutraOnline.</p>\r\n\r\n<p>Renowned artisan Shri Margi Vijayakumar, known for his portrayal of female roles, has designed this Kathakali presentation. The conundrum faced by a demoness, the magical power of a mother’s love, and the majesty of Lord Krishna, forms the bedrock for this tantalizing production.</p>\r\n\r\n<p><a href=\"https://www.natyasutraonline.com/kathakali/margi-vijayakumar/master-class-poothana-moksham\">Click here for the Master Class.</a></p>', '', NULL, 0, NULL, '', NULL, 'poothanamoksham-live-now.jpg', '', 'Poothanamoksham Live Now!', '1970-01-01', '', '', '', 0, 1, '2020-06-08 13:03:52', 1, '202.88.244.195', '2023-06-13 05:23:47', 10, '49.37.235.73', NULL, NULL, NULL, 'poothanamoksham-kathakali-master-class', 'Learn Poothana Moksham: Kathakali Master Class by Shri Margi Vijayakumar', 'Latest, kathakali, master class, poothana moksha, kerala art form, traditional', 'The Liberation of a Demoness is upon us! The Poothana Moksham or Deliverance of Poothana is now streaming exclusively on NatyaSutraOnline. Renowned artisan Shri Margi Vijayakumar, known for his portrayal of female roles, has designed this Kathakali presentation. The conundrum faced by a demoness, the magical power of a mother’s love, and the majesty of Lord Krishna, forms the bedrock for this tantalizing production.'),
(17, 'Odissi Beginners Lessons Live Now!', 1, 'n', NULL, '<p>The Eastern Shore has awakened! <br>\r\nFrom the heart of Odisha, we bring a new beginner’s series in the ancient art form, Odissi. </p>\r\n\r\n<p>The entire program is helmed by the renowned practitioner and instructor, Guru Sujata Mohapatra.  <br>\r\nShe has devised a thorough regimen to instruct and introduce the teachings of her Guru, Padma Vibhushan Kelucharan Mohapatra. </p>\r\n\r\n<p>The lessons from the mind that revitalized Odissi in India now available exclusively <a href=\"https://www.natyasutraonline.com/odissi/sujata-mohapatra-kelucharan/beginners-fundamental-video-lessons\">here</a>!</p>', 'Odissi Beginners Lessons', NULL, 0, NULL, '', NULL, 'odissi-beginners-lessons-coming-soon.jpg', '', 'Odissi Beginners Lessons Live Now!', '1970-01-01', '', '', '', 0, 1, '2020-07-02 13:45:39', 1, '61.2.215.254', '2023-06-13 05:23:34', 10, '49.37.235.73', NULL, NULL, NULL, 'odissi-beginners-lessons-techniques-of-guru-kelucharan-mohapatra-by-sujata-mohapatra', 'Learn Odissi Techniques of Guru Kelucharan Mohapatra\r\nby Sujata Mohapatra', 'odissi, classical dance, odisha, basics, techniques, indian dance, odia', 'From the heart of Odisha, we bring a new beginner’s series in the ancient art form, Odissi. \r\nThe entire program is helmed by the renowned practitioner and instructor, Guru Sujata Mohapatra.  \r\nShe has devised a thorough regimen to instruct and introduce the teachings of her Guru, Padma Vibhushan Kelucharan Mohapatra. \r\nThe lessons from the mind that revitalized Odissi in India shall soon be available exclusively on NatyaSutraOnline.'),
(18, 'Cholkettu, Mohiniyattam composition Live Now!', 1, 'n', NULL, '<p>The next turn in our Mohiniyattam journey is around the corner!</p>\r\n\r\n<p>Cholkettu represents the initiation rites that lead-off a performance, and Guru Smitha Rajan presents a comprehensive lesson on the same. The Cholkettu comprises of invocation rituals that pay homage to Sri Parvathi-Parameshwara and Devi Saraswathi, divine entities that are dear to every danseuse.</p>\r\n\r\n<p>The complete lesson iss available here - <a href=\"https://www.natyasutraonline.com/mohiniyattam/smitha-rajan/composition-cholkettu\">https://bit.ly/CholkettuNSO</a></p>', '', NULL, 0, 20, 'd', NULL, 'cholkettu-mohiniyattam-composition-coming-soon.jpg', NULL, 'Cholkettu, Mohiniyattam composition Live Now!', '1970-01-01', '', '', '', 0, 0, '2020-07-31 05:23:09', 1, '117.199.7.139', '2023-02-24 07:24:18', 1, '61.2.215.254', NULL, NULL, NULL, 'cholkettu-mohiniyattam-composition', 'Cholkettu, Mohiniyattam composition Coming soon!', 'Cholkettu, Mohiniyattam composition, Coming soon, Mohiniyattam Tutorials', 'Latest updates on Natyasutraonline - New Mohiniyattam composition coming soon.'),
(19, 'NatyaSutraOnline turns one!', 1, 'n', NULL, '<p><b>#NatyaSutraDanciversary</b></p>\r\n\r\n<p>NatyaSutra is officially one-year-old!<br>\r\n<br>\r\nNovember 1st is around the corner, and Team NatyaSutraOnline celebrates its first anniversary. These 365 days are a testament to the journey we&#39;ve embarked alongside our valuable users, whose support has solidified our resolve. This special NatyaSutra Danciversary belongs to our global family, and we would love to engage with your video snippets, chronicling your journey with us. </p>\r\n\r\n<p>Join us in our virtual celebration by capturing and sharing your practice or performance bytes you learnt from us!</p>\r\n\r\n<p><a href=\"http://www.facebook.com/natyasutraonline\">Facebook</a> | <a href=\"http://www.instagram.com/natyasutraonline/\">Instagram</a> </p>\r\n\r\n<p> </p>', 'NatyaSutraOnline celebrates first anniversary on November 1st!', NULL, 0, 0, 'd', NULL, 'natyasutraonline-is-officially-a-one-year-old.jpg', NULL, 'NatyaSutraOnline turns one!', '1970-01-01', '', '', '', 0, 1, '2020-10-30 07:40:47', 4, '61.2.215.254', '2021-02-18 11:45:18', 4, '61.2.215.254', NULL, NULL, NULL, 'nso-anniversary', 'NatyaSutraOnline turns one!', 'Anniversary, dance, classical dance, indian classical art forms, elearning', 'NatyaSutraOnline the new normal elearning platform for Indian Classical Arts and Culture turns one year this November 1st.'),
(20, 'During lockdown, all the virtual world\'s a stage', 2, 'n', NULL, '', '', NULL, 0, 0, 'd', NULL, 'during-lockdown-all-the-virtual-worlds-a-stage1.jpg', NULL, 'During lockdown, all the virtual world\'s a stage', '2020-05-17', 'The Hindu', 'During-lockdown-all-the-virtual-world’s-a-stage-The-Hindu.pdf', 'https://www.thehindu.com/news/national/kerala/when-the-stage-goes-virtual/article31608491.ece', 2, 1, '2021-01-14 10:12:00', 1, '202.88.244.195', '2021-03-08 07:53:32', 1, '202.88.244.195', NULL, NULL, NULL, '', '', '', ''),
(21, 'That Inexplicable Tenth Rasa From An Actor-Dancer Who Collapsed And Died On Stage', 2, 'n', NULL, '', '', NULL, 0, 0, 'd', NULL, 'that-inexplicable-tenth-rasa-from-an-actor-dancer-who-collapsed-and-died-on-stage.jpg', NULL, 'That Inexplicable Tenth Rasa From An Actor-Dancer Who Collapsed And Died On Stage', '2018-01-31', 'Outlook', 'Ottan-Thullal-Geethanandan-Dancer-Who-Collapsed-On-Stage-Tenth-Rasa.pdf', 'https://www.outlookindia.com/website/story/that-inexplicable-tenth-rasa-from-an-actor-dancer-who-collapsed-on-stage/307613', 2, 1, '2021-01-14 10:30:08', 1, '202.88.244.195', '2021-03-04 09:53:06', 1, '202.88.244.195', NULL, NULL, NULL, '', '', '', ''),
