INSERT INTO `tb_vgallery` (`id`, `name`, `gita_govinda_page_id`, `guru_id`, `display_in`, `short_descr`, `description`, `display_order`, `event_related`, `event_id`, `from_date`, `to_date`, `home_page_image`, `file_name`, `page_title`, `meta_keywords`, `meta_description`, `noindex`, `added_by`, `added_on`, `added_by_ip`, `updated_by`, `updated_on`, `updated_by_ip`, `deleted_by`, `deleted_on`, `deleted_by_ip`, `status`) VALUES
(1, 'Videos of Guru Pali Chandra', NULL, 1, 'a', 'Videos of Guru Pali Chandra', 'Videos of Guru Pali Chandra', 63, 'y', 0, '2020-11-27', NULL, NULL, 'kathak-videos', 'Videos of Kathak Guru Pali Chandra', 'kathak videos, Guru Pali Chandra', 'Videos of Guru Pali Chandra', 'n', 1, '2020-11-27 07:13:04', '202.88.244.195', 1, '2021-04-08', '49.37.191.24', 0, '0000-00-00 00:00:00', '', 1),
(2, 'First Danciversary', NULL, 0, NULL, '', 'We successfully completed a year long journey in the new learning platform and we couldn’t think of any celebrations without our beloved community members! \r\nSo we asked them to share their favorite NatyaSutraOnline compositions by their respected Gurus.\r\n\r\nWe are pleased to have such an overwhelming response and making it a grant online celebration! ', 78, 'y', 0, '2021-01-18', NULL, NULL, 'danciversary-title', 'Danciversary Videos', 'Anniversary videos, performance videos, dance sessions, online celebration', 'NatyaSutraOnline celebrated first anniversary celebrations online by inviting community members to participate by sharing a performance video from the lessons available in the website.', 'n', 4, '2021-01-18 08:14:35', '61.2.215.254', 0, '0000-00-00', '', 4, '2021-02-07 07:54:19', '202.88.234.146', 2),
(3, 'First Danciversary', NULL, 0, NULL, '', 'We successfully completed a year long journey in the new learning platform and we couldn’t think of any celebrations without our beloved community members! \r\nSo we asked them to share their favorite NatyaSutraOnline compositions by their respected Gurus.\r\n\r\nWe are pleased to have such an overwhelming response and making it a grant online celebration! ', 77, 'y', 0, '2021-01-18', NULL, NULL, 'danciversary-title', 'Danciversary Videos', 'Anniversary videos, performance videos, dance sessions, online celebration', 'NatyaSutraOnline celebrated first anniversary celebrations online by inviting community members to participate by sharing a performance video from the lessons available in the website.', 'n', 4, '2021-01-18 08:14:43', '61.2.215.254', 0, '0000-00-00', '', 4, '2021-02-07 07:54:09', '202.88.234.146', 2),
(4, 'First Anniversary Celebration', NULL, 0, 'g', 'NatyaSutraOnline celebrates first anniversary on 1st November 2020. ', '<p><strong>1st November 2020</strong><br>\r\nNatyaSutraOnline celebrated first anniversary on 1st November 2020! We successfully completed a year long journey in the new learning platform and we couldn’t think of any celebrations without our beloved community members!<br>\r\nSo we asked them to share their favorite NatyaSutraOnline compositions by their respected Gurus. We are pleased to have such an overwhelming response and making it a grant online celebration!<br>\r\n<strong>#NatyaSutraDanciversary</strong></p>\r\n', 64, 'y', 0, '2021-01-21', NULL, 'first-anniversary-celebration.webp', 'first-anniversary-celebration', 'NatyaSutraOnline Danciversary', 'Anniversary videos, performance videos, dance sessions, online celebration', 'NatyaSutraOnline celebrated first anniversary celebrations online by inviting community members to participate by sharing a performance video from the lessons available in the website.', 'n', 4, '2021-01-21 08:32:14', '61.2.215.216', 1, '2022-10-14', '171.49.217.187', 0, '0000-00-00 00:00:00', '', 1),
(5, 'Special videos', 0, 0, 'g', 'This page contains special video greetings produced by Team NatyaSutraOnline since its inception. These commemorate specific celebrations, festivals, and global events of consequence in the dance community. ', '<p><strong>NatyaSutra Specials</strong><br>\r\nThis page contains special video greetings produced by Team NatyaSutraOnline since its inception.<br>\r\nThese commemorate specific celebrations, festivals, and global events of consequence in the dance community. </p>\r\n', 35, 'y', 0, '2021-05-01', NULL, 'special-videos.webp', 'greetings', 'Greetings / Special Videos', 'Greetings ,  Special Videos', 'Greetings and special videos from NatyaSutraOnline', 'n', 1, '2021-05-01 08:48:12', '116.68.79.36', 19, '2026-06-25', '157.46.10.37', 0, '0000-00-00 00:00:00', '', 1),
(6, 'Second Anniversary Celebration', NULL, 0, 'g', 'NatyaSutraOnline celebrated its Second Anniversary on 1st November 2021.', '<p><strong>1st November 2021</strong><br>\r\nNovember 1st, we celebrated the 2nd edition of NatyaSutraOnline&#39;s inception. <br>\r\nThis event is a yearly reminder that our amazing global dance community has propelled NatyaSutra to greater heights. The new courses, art forms, and maestros under the NatyaSutra umbrella are testament to this support.<br>\r\n<strong>#NatyaSutraDanciversary</strong></p>\r\n', 34, 'y', 0, '2021-11-20', NULL, 'second-anniversary-celebration.webp', 'secondary-anniversary', 'NatyaSutraOnline 2nd Danciversary', 'Anniversary videos, performance videos, dance sessions, online celebration, dance videos, dance tutorials, Kathak, Bharatanatyam, Odissi, Kuchipudi, Mohiniyattam', 'Inviting our community members to take part in our virtual celebrations. ', 'n', 4, '2021-11-20 15:43:01', '103.155.222.172', 1, '2022-10-15', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(7, 'Second Anniversary Celebration', NULL, 0, 'g', 'NatyaSutraOnline celebrated its second anniversary on 1st November 2021! ', '<p>NatyaSutraOnline celebrated its second anniversary on 1st November 2021! We successfully completed two years long journey in the new learning platform and we couldn’t think of any celebrations without our beloved community members!</p>\r\n\r\n<p>So we asked them to share their favorite NatyaSutraOnline compositions by their respected Gurus. We are pleased to have such an overwhelming response and make it a grant online celebration!</p>\r\n\r\n<p> #natyasutraonline </p>\r\n', 66, 'y', 0, '2022-01-04', NULL, NULL, 'varun-khanna-ardhanareeshwara-ashtakam', 'Ardhanareeswara Ashtakam, Bharatanatyam Performance by Varun Khanna | 2nd Danciversary Celebrations', 'ardhanareeswara ashtakam,bharatanatyam, learn bharatanatyam,Danciversary celebration,rama vaidyanathan,2nd dance anniversary, Natyasutraonline, dance anniversary, bharatanatyam compositions, learn bharatanatyam from rama vaidyanathan, learn bharatanatyam,learn bharatanatyam online, bharatanatyam classical dance, ardhanareeswara stotram', 'Celebrating the dual nature of life!\r\nHere is Varun Khanna, participating in our 2nd Danciversary Celebrations by performing Ardhanareeswara Ashtakam, Bharatanatyam composition by  Smt. Rama Vaidyanathan. \r\n\r\nThank you for being part of our journey! \r\n\r\nTo learn this composition, visit: https://bit.ly/RArdhanareeswara', 'n', 13, '2022-01-04 11:04:32', '202.88.244.195', 0, '0000-00-00', '', 13, '2022-01-04 11:25:38', '202.88.244.195', 2),
(8, 'Our Most Viewed Catalogue', 0, 0, 'g', 'The YouTube videos here are all time favourites and have successfully reached more than one lac plus videos', '<p>The YouTube videos in this section are crowd favourites that have garnered a minimum of 1 lakh or 100,000 views. They represent the most beloved, viral and insightful lectures and compositions  in our entire catalogue on Indian art, music and culture. Browsing through these gives one a good idea of the popularity and quality of our exhaustive digital collection of Indian classical dance instructional videos.</p>\r\n\r\n<p> </p>\r\n', 9, 'y', 0, '2022-10-11', NULL, 'our-most-viewed-catalogue.webp', 'most-viewed-youtube-videos-million-views', 'Most Viewed Youtube Videos | One Million plus Views', 'Our Most Viewed Videos, 1 Million Views, most viewed youtube videos,  most viewed music video on youtube, how much is 1 million youtube views worth, Image of 1 million plus Views, Image of 1 million views sticker, 1 million views sticker', 'The YouTube Videos here are all time favourites and have successfully reached more than one lac plus videos', 'n', 1, '2022-10-11 12:09:43', '171.49.217.187', 19, '2026-09-10', '49.37.226.45', 0, '0000-00-00 00:00:00', '', 1),
(9, 'test 14-10-2022', NULL, 0, 'b', '', '', 33, 'y', 0, '2022-10-14', NULL, 'BANNER.jpg', 'tt', 'tt', 'tt', 'test ok', 'n', 1, '2022-10-14 07:06:33', '202.88.244.195', 1, '2022-10-14', '202.88.244.195', 1, '2023-05-14 07:19:00', '49.37.234.32', 2),
(10, 'Gita Govinda by Guru Pali Chandra', 0, 1, 'g', 'Videos related to All 24 songs Gita Govinda, Jayadeva’s immortal poetic work was composed in the 12th century by Guru Pali Chandra in Kathak dance style', '<p>Jayadeva&#39;s Gita Govinda - A Poet A Song and A Story<br>For the first time in India’s recorded history, all 24 songs of the Gita Govinda are choreographed and composed. Kathak icon Guru (Dr.) Pali Chandra helms this super mega project. The 12th-century Sanskrit poem is an ode to Lord Krishna by Jayadeva, and the Guru plans to represent all facets of the original composition. Upon completion, this shall be one of India’s premier artistic endeavours of the modern era. The project has been rolling for almost for half a decade, with over 200 people involved in the production. Guru Dr Pali Chandra wanted to combine and recreate all the poem&#39;s stanzas, as this has never been done before. This section features some interesting videos related to this project. </p>', 8, 'y', 0, '2023-05-24', NULL, 'gita-govinda-by-guru-pali-chandra.webp', 'gita-govinda-pali-chandra', 'Videos related to  Jayadeva’s Gita Govinda by Guru Pali Chandra in Kathak', 'Gita Govinda Videos, Guru Pali Chandra, Gita Govinda, Jayadeva, Love story, Kathak dance, Krishna Radha Love, Epic Journey, Prabandha, Sanskrit', 'Videos related to All 24 songs Gita Govinda, Jayadeva’s immortal poetic work was composed in the 12th century by Guru Pali Chandra in Kathak dance style', 'n', 10, '2023-05-24 07:25:21', '61.2.215.216', 1, '2025-02-25', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(11, 'test video gallery', 3, 0, 'e', '', '', 14, 'y', 0, '2023-07-15', NULL, 'test-video-gallery.webp', 'sdfsdfsd', 'sdfsdf', 'sdfsdf', 'sdfsd', 'n', 1, '2023-07-15 06:17:07', '202.88.244.195', 1, '2023-07-15', '202.88.244.195', 1, '2023-07-15 06:20:20', '202.88.244.195', 2),
(12, 'Guru Pranam: Paying Homage to Our Esteemed Gurus', 0, 0, 'g', 'Guru Pranam is a gesture of deep respect and gratitude offered to a teacher for their guidance and wisdom.', '<p>This section of Natyasutra celebrates the timeless tradition of Guru Pranam, which is an expression of deep gratitude and respect towards one&#39;s teachers and mentors. Through specially curated videos, our artists and students pay tribute to legendary gurus who have significantly shaped their lives and artistic journeys.<br>\r\nWitness moments of heartfelt reverence on occasions like Guru Purnima and Teacher’s Day, captured through sincere gestures, words of gratitude, and felicitation. These videos highlight the profound bond between teacher and student, emphasizing humility, devotion, and appreciation. These heartfelt homages honor the role of gurus in preserving and nurturing the arts and upholding our culture.</p>\r\n', 2, 'y', 0, '2025-07-10', NULL, 'guru-pranam1.webp', 'guru-pranam', 'Guru Pranam – A Tribute of Respect to the Teacher', 'Guru Pranam, meaning of Guru Pranam, Indian tradition, respect to teachers, teacher tribute, Guru Purnima, Indian classical arts, guru-shishya tradition, guru purnima', 'Discover the meaning and significance of Guru Pranam, a traditional gesture of reverence and gratitude offered to teachers in Indian culture.', 'n', 19, '2025-07-10 06:45:08', '49.37.226.46', 19, '2025-07-17', '49.37.227.86', 0, '0000-00-00 00:00:00', '', 1),
(13, 'test 18-10-2025', 0, 0, 'g', '', '', 1, 'y', 0, '2025-10-18', NULL, 'test-18-10-2025.webp', 'test18', 'test18', 'test18', 'test18', 'n', 1, '2025-10-18 09:41:09', '202.88.244.195', 0, '2025-10-18', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 0);
INSERT INTO `tb_vgallery_videos` (`id`, `vgallery_id`, `video_type`, `v_caption`, `v_code`, `v_description`, `image_name`, `cover_display`, `display_order`, `filename`, `page_title`, `meta_keyword`, `meta_description`, `added_by`, `added_on`, `added_by_ip`, `updated_by`, `updated_on`, `updated_by_ip`, `deleted_by`, `deleted_on`, `deleted_by_ip`, `status`) VALUES
(1, 1, 0, 'Life and Kathak with Guru Pali Chandra', 'https://www.youtube.com/watch?v=VzA_06FWwZI', 'Journey Over Destination is the message that Kathak maestro Guru Pali Chandra shares with her students.  NatyaSutraOnline shall play a crucial role in preserving classical Indian dance forms online. Gurus approach towards her art and the advice she has for novices are included here as well.', '', 'n', 1, 'life-and-kathak-with-guru-pali-chandra', 'Life and Kathak with Guru Pali Chandra', 'Life and Kathak with Guru Pali Chandra, Famous Kathak Dancer of Lucknow Gharana', 'Life and Kathak with Guru Pali Chandra, , Famous Kathak Dancer of Lucknow Gharana', 1, '2020-11-27 07:13:04', '202.88.244.195', 0, '2021-04-28 07:54:37', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(2, 1, 0, 'Kathak Maestro Guru Pali Chandra\'s bond with her Ghungroos', 'https://www.youtube.com/watch?v=Lz3uiRSs88w', '   ', '', NULL, 3, 'kathak-maestro-guru-pali-chandra-ghungroos', 'Kathak Maestro Guru Pali Chandra\'s bond with her Ghungroos', 'Kathak Maestro Guru Pali Chandra\'s bond with her Ghungroos', 'Kathak Maestro Guru Pali Chandra\'s bond with her Ghungroos', 0, '2020-11-27 07:21:43', '202.88.244.195', 0, '2021-02-26 06:36:57', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(3, 1, 0, 'Guru Pali Chandra\'s Expectations from Her Online Students', 'https://www.youtube.com/watch?v=Qf5e1Bj_hw0', '   ', '', NULL, 4, 'guru-pali-chandras-expectations', 'Guru Pali Chandra\'s Expectations from Her Online Students', 'Guru Pali Chandra\'s Expectations from Her Online Students', 'Guru Pali Chandra\'s Expectations from Her Online Students', 0, '2020-11-27 07:25:20', '202.88.244.195', 0, '2021-02-26 06:37:55', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(4, 4, 0, '1st Danciversary Celebration', 'https://www.youtube.com/watch?v=CODvF5V3o7c', 'NatyaSutraOnline celebrated first anniversary celebrations online by inviting community members to participate by sharing a performance video from the lessons available in the website.', '', 'n', 0, 'danciversay-title-video', 'Danciversay Title Video', 'Danciversay Title', 'Danciversay Title', 4, '2021-01-21 08:32:14', '61.2.215.216', 0, '2021-02-26 11:32:01', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(5, 4, 0, 'Pushpanjali Performance by Varun Khanna', 'https://www.youtube.com/watch?v=8Zjl7bBcO84', 'Thank you Varun Khanna, for being a part of NatyaSutra’s one-year-long journey!\r\nWe are so grateful to see you performing Pushpanjali by Guru Rama Vaidyanathan as part of our 1st Danciversary Celebrations.   ', '', NULL, 0, 'pushpanjali-performance-varun-khanna', 'Pushpanjali Performance by Varun Khanna', 'Pushpanjali Performance by Varun Khanna', 'Pushpanjali Performance by Varun Khanna', 0, '2021-01-22 05:56:59', '202.88.244.195', 0, '2021-02-26 06:02:20', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(6, 4, 0, 'Odissi Performance by Meghna Ganguly', 'https://www.youtube.com/watch?v=k_7YZZDtVbs', 'Watch Meghna Ganguly showcasing a delightful performance participating in the first danciversary of Natyasutra! \r\nWe are so grateful to see you perform Odissi by Vidushi Sujata Mohapatra. Dance more, let your passion shine through!   ', '', NULL, 0, 'odissi-performance-meghna-ganguly', 'Odissi Performance by Meghna Ganguly', 'Odissi Performance by Meghna Ganguly', 'Odissi Performance by Meghna Ganguly', 0, '2021-01-22 05:58:01', '202.88.244.195', 0, '2021-02-26 06:04:19', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(7, 4, 0, 'Bharatanatyam by Aparna Pisharody', 'https://www.youtube.com/watch?v=YICCGcp2ih0', 'A celebration of togetherness!\r\n\r\nThank you Aparna for participating in our 1st Danciversary.\r\nWe are pleased to see you stage Sita\'s Voice by RAMA VAIDYANATHAN.   ', '', NULL, 0, 'bharatanatyam-by-aparna-pisharody', 'Bharatanatyam by Aparna Pisharody', 'Bharatanatyam by Aparna Pisharody', 'Bharatanatyam by Aparna Pisharody', 0, '2021-01-22 05:59:56', '202.88.244.195', 0, '2021-02-26 06:05:23', '202.88.244.195', 19, '2026-07-30 05:59:14', '223.181.10.64', 2),
(8, 4, 0, 'Sri Chakra Raja - Mohiniyattam Performance by Amrutha Nair', 'https://www.youtube.com/watch?v=z6njEHQZOBU&feature=youtu.be', 'Believe in your inner strength!\r\nForget everything and submit yourself to the Shakthi of Nritya.\r\n\r\nWith a ravishing Mohiniyattam performance on Sri Chakra Raja composition, Amrutha participates in our first Danciversary.   ', '1-07022021080818.jpg', NULL, 0, 'sri-chakra-raja-mohiniyattam-performance-by-amrutha-nair', 'Sri Chakra Raja - Mohiniyattam Performance by Amrutha Nair', 'Sri Chakra Raja - Mohiniyattam Performance by Amrutha Nair', 'Sri Chakra Raja - Mohiniyattam Performance by Amrutha Nair', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:05:56', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(9, 4, 0, 'Odissi Performance by Arpita Ganguly', 'https://www.youtube.com/watch?v=xoXivzothmo&feature=youtu.be', 'NatyaSutraOnline is beyond proud to show you the Odissi performance of Arpita Ganguly. It\'s a pleasure to see such talented hearts participating in our first Danciversary.\r\n\r\nThank you for being a part of our journey! ??    ', '2-07022021080818.jpg', NULL, 0, 'odissi-performance-by-arpita-ganguly', 'Odissi Performance by Arpita Ganguly', 'Odissi Performance by Arpita Ganguly', 'Odissi Performance by Arpita Ganguly', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:30:20', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(10, 4, 0, 'Lament to the Birds by Gauri Bhobe', 'https://www.youtube.com/watch?v=B7zZKz2Sqlc&feature=youtu.be', ' It\'s true that dancers don\'t need wings to fly.\r\nWatch Gauri Bhobe happily flying with hues of joy and pride as she performs \"Lament to the Birds\" by Rama Vaidyanathan.\r\n\r\nThank you for participating in our first Danciversary showcasing a composition of our own beloved guru.   ', '3-07022021080818.jpg', NULL, 0, 'lament-to-the-birds-by-gauri-bhobe', 'Lament to the Birds by Gauri Bhobe', 'Lament to the Birds by Gauri Bhobe', 'Lament to the Birds by Gauri Bhobe', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:30:55', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(11, 4, 0, 'Oriya Abhinaya by Monali Mazumda', 'https://www.youtube.com/watch?v=wvuaAeuGNRI&feature=youtu.be', ' Always have faith in how far you can go and how far you have come!\r\n\r\nExtremely proud & happy to see the joyful journey of Monali as an amazing dancer. Thank you for participating in our first Danciversary celebrations by performing an Oriya Abhinaya piece.   ', '4-07022021080818.jpg', NULL, 0, 'oriya-abhinaya-by-monali-mazumda', 'Oriya Abhinaya by Monali Mazumda', 'Oriya Abhinaya by Monali Mazumda', 'Oriya Abhinaya by Monali Mazumda', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:31:35', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(12, 4, 0, 'Yeppadi Manam Abhinaya Performance by Akshaya', 'https://www.youtube.com/watch?v=RL42KZ_y2GU&feature=youtu.be', ' Embrace your blessings and express your feelings to the world through the language of Mudras!\r\nWatch Akshaya participating in our first Danciversary performing ‘Yeppadi Manam’   ', '5-07022021080818.jpg', NULL, 0, 'yeppadi-manam-abhinaya-performance-by-akshaya', 'Yeppadi Manam Abhinaya Performance by Akshaya', 'Yeppadi Manam Abhinaya Performance by Akshaya', 'Yeppadi Manam Abhinaya Performance by Akshaya', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:32:05', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(13, 4, 0, '\'Guru Vandana\' - Kathak performance by Moumita Choudhury', 'https://www.youtube.com/watch?v=SCA3Z-YfNJ0&feature=youtu.be', 'Lose yourself to dance!\r\nWatch Moumita, a Kathak student performing ‘Guru Vandana’.    ', '6-07022021080818.jpg', NULL, 0, 'guru-vandana-kathak-performance-by-moumita-choudhury', '\'Guru Vandana\' - Kathak performance by Moumita Choudhury', '\'Guru Vandana\' - Kathak performance by Moumita Choudhury', '\'Guru Vandana\' - Kathak performance by Moumita Choudhury', 0, '2021-02-07 08:08:18', '202.88.234.146', 0, '2021-02-26 06:32:39', '202.88.244.195', 0, '0000-00-00 00:00:00', '', 1),
(14, 4, 0, 'Ennadu Jutuno ... Vocal by Sreenivasan', 'https://www.youtube.com/watch?v=frLkSk_bAq0', 'The best way to get connected to the world is through the language of music!\r\nWatch Sreenivasan finding his way to our soul through a beautiful rendition of Ennadu Jutuno…\r\nThank you for participating in our first Anniversary!', '1-14032021081153.jpg', NULL, 0, 'ennadu-jutuno-by-sreenivasan', 'Ennadu Jutuno by Sreenivasan', 'Ennadu Jutuno, Carnatic Music', 'Ennadu Jutuno by Sreenivasan', 0, '2021-03-14 08:11:53', '202.88.234.146', 0, '2021-03-14 08:13:17', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 1),
(15, 4, 0, 'Mohiniyattam Performance | Cholkettu by Neha', 'https://www.youtube.com/watch?v=v1gT7ilR2Vw', 'Do more of what makes you happy always!\r\nThank you Neha for participating in NatyaSutraOnline’s Danciversary by performing the Mohiniyattam composition Cholkettu.', '1-14032021082035.jpg', NULL, 0, 'cholkettu-by-neha', 'Cholkettu by Neha', 'Cholkettu, Mohiniyattam', 'Mohiniyattam Cholkettu Performance by Neha', 0, '2021-03-14 08:20:35', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(16, 4, 0, 'Ardhanareeswara Ashtakam | Bharatanatyam Performance by Keerthi', 'https://www.youtube.com/watch?v=y54jS91PuAw', ' Let your dreams be your rhythm and let that rhythm brings happiness to you!\r\nWatch a blissful Bharatanatyam performance by Keerthi. \r\nThank you for showering us with your rhythm of joy on our first Danciversary!', '2-14032021082035.jpg', NULL, 0, 'ardhanareeswara-ashtakam-performance-by-keerthi', 'Ardhanareeswara Ashtakam by Keerthi', 'Ardhanareeswara Ashtakam, Bharatanatyam', 'Ardhanareeswara Ashtakam Performance by Keerthi', 0, '2021-03-14 08:20:35', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(17, 4, 0, 'Ashtapadi - Chandana Charchita by Madhavi', 'https://www.youtube.com/watch?v=QF-qUvw4z2s', ' Passion is truly priceless!\r\nWatch Madhavi showcasing her passion for Odissi participating in our first Danciversary.\r\nThank you and never stop dancing!', '3-14032021082035.jpg', NULL, 0, 'ashtapadi-chandana-charchita-odissi-performance-by-madhavi', 'Ashtapadi - Chandana Charchita | Odissi performance by Madhavi', 'Ashtapadi, Odissi', 'Ashtapadi - Chandana Charchita | Odissi performance by Madhavi', 0, '2021-03-14 08:20:35', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(18, 4, 0, 'Om Jayanti Mangala Kali by Ananya', 'https://www.youtube.com/watch?v=drjJNyK6N5E', ' Dance is a harmony parallel with happiness!\r\n\r\nWatch Ananya Sathish happily dancing with immense pride and enthusiasm.\r\nThank you for participating in our first Dancivesary by performing Kathak composition Om Jayanti.', '', NULL, 0, 'om-jayanti-mangala-kali-by-ananya', 'Om Jayanti Mangala Kali | Kathak Performance by Ananya', 'Om Jayanti Mangala Kali, Kathak', 'Om Jayanti Mangala Kali by Ananya', 0, '2021-03-14 08:20:35', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(19, 4, 0, 'Sivoham, Bharatanatyam Performance by Bindu Balan', 'https://www.youtube.com/watch?v=IgZCgBQCw7U', 'Let your heartbeat be your rhythm for dance!\r\nShowcase your love for dance just like Bindu Balan, making our first Danciversary joyful!', '1-14032021082752.jpg', NULL, 0, 'sivoham-by-bindu-balan', 'Sivoham by Bindu Balan', 'Sivoham, Bharatanatyam Performance', 'Sivoham, Bharatanatyam Performance by Bindu Balan', 0, '2021-03-14 08:27:52', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(20, 4, 0, 'Bhogeendra Sayinam by Ayana Perla', 'https://www.youtube.com/watch?v=HE3-CgVMI9k', ' Chase your passion and keep dancing! \r\nThank You Ayana for making your passion a part of our first Danciversary. \r\nWatch this brilliant artist and her amazing depiction of Bhogeendra Sayinam composition.  ', '2-14032021082752.jpg', NULL, 0, 'bhogeendra-sayinam-by-ayana-perla', 'Bhogeendra Sayinam by Ayana Perla', 'Bhogeendra Sayinam, Bharatanatyam Performance', 'Bhogeendra Sayinam Performance by Ayana Perla', 0, '2021-03-14 08:27:52', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(21, 4, 0, 'The Divine Cowherd by Janani', 'https://www.youtube.com/watch?v=kgPz_2c9EDY', ' Watch Janani making her day special by participating in our first Danciversary! It\'s our pleasure to see you perform Divine Cowherd by Guru Rama Vaidyanathan.', '3-14032021082752.jpg', NULL, 0, 'the-divine-cowherd-by-janani', 'The Divine Cowherd by Janani', 'The Divine Cowherd, Bharatanatyam Performance', 'The Divine Cowherd Performance by Janani', 0, '2021-03-14 08:27:53', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(22, 4, 0, 'Krishna Vandana Performance by Harshita Mahesh', 'https://www.youtube.com/watch?v=Sh5k01_n-KI', ' Watch Harshita showcasing her passion for Kathak, participating in our first Danciversary!\r\nWe are humbled to see you perform Krishna Vandana from our Intermediate Lessons by Guru Pali Chandra.', '4-14032021082753.jpg', NULL, 0, 'krishna-vandana-by-harshita-mahesh', 'Krishna Vandana Performance by Harshita Mahesh', 'Krishna Vandana, Kathak Performance', 'Krishna Vandana Performance by Harshita Mahesh', 0, '2021-03-14 08:27:53', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(23, 4, 0, 'Sita\'s Voice Performance by Rachana Rao', 'https://www.youtube.com/watch?v=Kc-iCxB1IFc', ' Thank you Rachana Rao for staying with us throughout our happy journey.\r\nWe are glad to see you perform Sita’s Voice by Guru Rama Vaidyanathan. ', '5-14032021082753.jpg', NULL, 0, 'sitas-voice-by-rachana-rao', 'Sita\'s Voice Performance by Rachana Rao', 'Sita\'s Voice, Bharatanatyam', 'Sita\'s Voice by Rachana Rao', 0, '2021-03-14 08:27:53', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(24, 4, 0, 'Kathak Performance by Aditi Nilesh', 'https://www.youtube.com/watch?v=2Zws8ykn0YA', 'Do more of what you love and what makes you complete.\r\nWe are glad to be a part of your dance dreams.\r\nThank you for participating in our first Danciversary.', '1-14032021083730.jpg', NULL, 0, 'kathak-performance-by-aditi-nilesh', 'Kathak Performance by Aditi Nilesh', 'Kathak Performance', 'Kathak Performance by Aditi Nilesh', 0, '2021-03-14 08:37:30', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 1, '2022-06-03 04:47:40', '171.49.191.254', 2),
(25, 4, 0, 'Neela Varnam Performance by Dhanya', 'https://www.youtube.com/watch?v=Qp6N31qJUC8', ' Keep dancing and stay happy! \r\nThank you Dhanya for participating in our first Danciversary by performing Neela Varnam. \r\nIt\'s our pleasure to showcase your talent to the world on behalf of #NatyaSutraDanciversary', '', NULL, 0, 'neela-varnam-performance-by-dhanya', 'Neela Varnam Performance by Dhanya', 'Neela Varnam, Bharatanatyam', 'Neela Varnam Performance by Dhanya', 0, '2021-03-14 08:37:30', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(26, 4, 0, 'Om Jayanti Mangala Kali  by Ritika Das', 'https://www.youtube.com/watch?v=mEX1R3mnGhk', ' Always do your best to make your days memorable!\r\nThank you for making our celebration memorable with your performance.\r\nWatch Ritika Das participating in our first Danciversary by performing Kathak composition Om Jayanti.', '3-14032021083730.jpg', NULL, 0, 'om-jayanti-mangala-kali-by-ritika-das', 'Om Jayanti Mangala Kali  by Ritika Das', 'Om Jayanti Mangala Kali, Kathak', 'Om Jayanti Mangala Kali  by Ritika Das', 0, '2021-03-14 08:37:30', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(27, 4, 0, 'Neela Varnam by Bhadra Sharma', 'https://www.youtube.com/watch?v=muDM2KiHo3Q', ' We are glad to share the amazing performance of a born artist!\r\nThank you, Bhadra for participating in our first Danciversary by performing Neela Varnam by Dr Rajashree Warrier.', '4-14032021083730.jpg', NULL, 0, 'neela-varnam-by-bhadra-sharma', 'Neela Varnam by Bhadra Sharma', 'Neela Varnam, Bharatanatyam', ' Neela Varnam by Bhadra Sharma', 0, '2021-03-14 08:37:30', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(28, 4, 0, 'Cholkettu by Athulya', 'https://www.youtube.com/watch?v=nSvWcV3qRGo', ' Do more of what makes you happy always!\r\nThank you Athulya for participating in our Danciversary by performing  Mohiniyattam composition - Cholkettu.', '5-14032021083730.jpg', NULL, 0, 'cholkettu-by-athulya', 'Cholkettu by Athulya', 'Cholkettu, Mohiniyattam', 'Cholkettu by Athulya', 0, '2021-03-14 08:37:31', '202.88.234.146', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(29, 4, 0, 'Aduvum Solluval by Arathy', 'https://www.youtube.com/watch?v=pO55aWfb9Ds&feature=youtu.be', 'With much love and pride, we present to you, Arathy, performing Aduvum Solluvaal by Dr. Rajashree Warrier. Thank you dear for participating in our first Danciversary!\r\n', '1-14032021104152.jpg', NULL, 0, 'aduvum-solluval-by-arathy', 'Aduvum Solluval by Arathy', 'Aduvum Solluval, Bharatanatyam', 'Aduvum Solluval by Arathy', 0, '2021-03-14 10:41:52', '61.2.215.216', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
