(34, 4, 0, 'Thumri by Anagha Nair', 'https://www.youtube.com/watch?v=D8zNboOPy5w', 'We are humbled to see you perform Kathak Thumri, Anagha.\r\nOur heartfelt thanks for being on our year-long journey.', '1-19032021053922.jpg', NULL, 0, 'thumri-by-anagha-nair', 'Thumri by Anagha Nair', 'Thumri, Kathak Dance', 'We are humbled to see you perform Kathak Thumri, Anagha.\r\nOur heartfelt thanks for being on our year-long journey.', 0, '2021-03-19 05:39:23', '61.2.215.254', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
(35, 4, 0, 'Pushpanjali by Pooja Natarajan', 'https://www.youtube.com/watch?v=-4QCvCJqpZ0', 'Do you know what is the best part of being an educator?\r\nSeeing our students bring out their best!\r\nThank you, Pooja, for showcasing the best to the world by participating in our first Danciversary.', '1-19032021054100.jpg', NULL, 0, 'pushpanjali-by-pooja-natarajan', 'Pushpanjali by Pooja Natarajan', 'Pushpanjali, Bharatanatyam', 'Do you know what is the best part of being an educator?\r\nSeeing our students bring out their best!\r\nThank you, Pooja, for showcasing the best to the world by participating in our first Danciversary.', 0, '2021-03-19 05:41:00', '61.2.215.254', 0, '0000-00-00 00:00:00', '', 0, '0000-00-00 00:00:00', '', 1),
